import { useEffect, useState } from 'react';
import { useEventCallback } from '@jbrowse/core/util/useEventCallback';
import useMeasure from '@jbrowse/core/util/useMeasure';
import { isAlive } from '@jbrowse/mobx-state-tree';
export function useFocusOnInteraction(ref, onInteract) {
    const stableOnInteract = useEventCallback(onInteract);
    useEffect(() => {
        function handleSelectView(e) {
            if (e.target instanceof Element && ref.current?.contains(e.target)) {
                stableOnInteract();
            }
        }
        document.addEventListener('mousedown', handleSelectView);
        document.addEventListener('keydown', handleSelectView);
        return () => {
            document.removeEventListener('mousedown', handleSelectView);
            document.removeEventListener('keydown', handleSelectView);
        };
    }, [ref, stableOnInteract]);
}
export function useDebounce(value, delay) {
    const [debouncedValue, setDebouncedValue] = useState(value);
    useEffect(() => {
        const handle = setTimeout(() => {
            setDebouncedValue(value);
        }, delay);
        return () => {
            clearTimeout(handle);
        };
    }, [value, delay]);
    return debouncedValue;
}
export function useWidthSetter(view, padding) {
    const [ref, { width }] = useMeasure();
    useEffect(() => {
        let token;
        if (width && isAlive(view)) {
            token = requestAnimationFrame(() => {
                view.setWidth(width);
            });
        }
        return () => {
            if (token) {
                cancelAnimationFrame(token);
            }
        };
    }, [padding, view, width]);
    return ref;
}
export function useLocalStorage(key, initialValue, enabled = true) {
    const [storedValue, setStoredValue] = useState(() => {
        if (typeof window === 'undefined' || !enabled) {
            return initialValue;
        }
        try {
            const item = window.localStorage.getItem(key);
            return item ? JSON.parse(item) : initialValue;
        }
        catch (error) {
            console.error(error);
            return initialValue;
        }
    });
    const setValue = (value) => {
        try {
            const valueToStore = typeof value === 'function'
                ? value(storedValue)
                : value;
            setStoredValue(valueToStore);
            if (typeof window !== 'undefined' && enabled) {
                window.localStorage.setItem(key, JSON.stringify(valueToStore));
            }
        }
        catch (error) {
            console.error(error);
        }
    };
    return [storedValue, setValue];
}
